import {footerBrandLink,headerBrandLink,BRAND_NAME} from '../brand/identity.js';
import {ICEO_SOURCES} from '../iceo/registry.js';
import {NEWS_PUBLISHERS} from '../iceo/news-sources.js';
import {NEWS_CATEGORIES} from '../iceo/news-taxonomy.js';
export const LEGAL_UPDATED='22 November 2026';
export const COMPANY={name:'DLKT Group OÜ',registry:'17335744',address:'Harju maakond, Tallinn, Lasnamäe linnaosa, Sepapaja tn 6, 15551, Estonia',email:'office@dlkt.ee',register:'https://ariregister.rik.ee/eng/company/17335744/DLKT-Group-O%C3%9C'} as const;
export type LegalSlug='about'|'terms'|'privacy'|'cookies'|'disclaimer'|'sources'|'accessibility'|'company'|'contact';
export interface LegalSection {readonly id:string;readonly title:string;readonly paragraphs:readonly string[]}
export interface LegalDocument {readonly updated?:string;readonly slug:LegalSlug;readonly title:string;readonly lead:string;readonly sections:readonly LegalSection[]}
const e=(v:string):string=>v.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const external=(text:string,url:string):string=>`<a href="${e(url)}" target="_blank" rel="noopener noreferrer">${e(text)}</a>`;
const mail=(subject:string):string=>`<a href="mailto:${COMPANY.email}?subject=${encodeURIComponent('DLKT · '+subject)}">${COMPANY.email}</a>`;
const publisherParagraphs=[...new Map(ICEO_SOURCES.map(s=>[s.publisher,s])).values()].map(s=>`${external(s.publisher,s.homepage)} · ${external('Publisher terms',s.termsUrl)}.`);
export const LEGAL_DOCUMENTS:readonly LegalDocument[]=[
 {slug:'about',updated:'22 November 2026',title:'Daily Life. Key Things.',lead:'A useful place to start your day, with the original source within reach.',sections:[
  {id:'service',title:'What DLKT does',paragraphs:['DLKT brings source-linked news and practical information into one continuous reader. The opening page contains up to twenty eligible articles. Further pages follow while you read, with a manual loading control as well. The stream rotates through the standard IPTC news categories without repeating a category before the other available categories have appeared in that round. Every eligible article in the connected catalogue remains reachable; older articles are not added to fill space. Each card retains its original publisher, publication date and source link.','The selected city determines the country edition. Available reporting from reviewed publisher editions in that country comes first within each category, followed by international reporting in the selected reading language. National edition describes publisher provenance, not the location of every reported event. Local news requires separately verified city coverage. The reader shows national, local and international coverage and makes a missing national supply explicit. Date, location and optional city-centre weather and dated currency references are separate from the news cards. Use my location requests browser permission only after you choose it; manual city selection remains available.']},
  {id:'control',title:'Your selection, your browser',paragraphs:['Reading is available without signing in. Save, Follow and Remember keep selected information in this browser. When account sign-in is available, your private profile can store optional name, language, timezone and interests, and you can explicitly import a reader copy into your account and restore it in another signed-in browser. This is not automatic cross-device sync. Followed categories remain in this browser. Paid checkout, a paid trial, scheduled briefing emails and background alerts are not activated.','Sources and geographic coverage are limited. DLKT does not search or verify every page on the web. <a href="/sources">See the method and connected sources</a>.']},
  {id:'wallet',title:'Info Wallet',paragraphs:['Info Wallet shows the current availability of account sign-in, private profile saving and optional email or social connections alongside the public daily briefing. When account sign-in is available, you can save optional Wallet preferences to your private account. Opening Wallet, signing in or saving a profile does not give DLKT access to your inbox or social accounts. An available connection requires your separate authorization with that provider.','When a provider connection is available and authorized, Check updates requests a bounded set of email metadata or comments. The homepage can show the five latest available updates and recheck while the page is visible and focused. This is not a complete activity history or background delivery. Account types, permissions and provider approval limits are explained in Wallet. Counts of views or shares do not identify everyone who viewed or shared a post. <a href="/wallet">Open Info Wallet</a>.']},
  {id:'organizations',title:'For organizations',paragraphs:['Local, Teams and Public are pilot proposals. The organization setup can open a filtered reader preview, explicitly remember the setup in this browser and prepare an email enquiry for your review. Organization publishing, paid plans, team accounts and automated delivery are not activated. <a href="/organizations">Explore the proposed plans</a>.']},
  {id:'kate',title:'Meet Kate',paragraphs:['Kate is DLKT’s visual muse, representing curiosity, clarity and useful discoveries. Her symbol accompanies the reader; publisher names, source dates and coverage limits remain visible.']},
  {id:'operator',title:'Who operates the service',paragraphs:[`DLKT is operated by ${COMPANY.name}, an Estonian company. <a href="/company">Company details</a> and <a href="/contact">contact routes</a> are available without an account.`]}
 ]},
 {slug:'terms',title:'Terms of use.',lead:'The conditions for using the current public DLKT service.',sections:[
  {id:'operator',title:'The service and its operator',paragraphs:[`These terms concern the DLKT platform at www.dlkt.ee, operated by ${COMPANY.name}, Estonian registry code ${COMPANY.registry}. Registered office: ${COMPANY.address}. Contact: ${mail('Service enquiry')}.`,'DLKT provides source-linked information, browser reading tools and the account features shown as available in the service. Public reading is currently free and does not start a subscription or a trial. No paid checkout, automatic charge or scheduled account delivery is activated. Any future paid service must state its price, taxes where applicable, features, renewal and cancellation conditions, trial conditions and applicable consumer rights before an explicit purchase. A saved profile or continued reading is not agreement to a charge.']},
  {id:'use',title:'Use the service responsibly',paragraphs:['Use the reader for lawful purposes. Do not interfere with access, probe for other people’s data, bypass access controls, misrepresent a source or use the service to distribute harmful material. Public availability is not permission to overload the service or republish a publisher’s protected content.','You remain responsible for checking the original source before relying on an update. A card’s extraction or source check is not a guarantee that a publisher’s statement is complete, correct, current or suitable for your situation. The <a href="/disclaimer">information disclaimer</a> explains the main limits.']},
  {id:'ownership',title:'Brand, software and source material',paragraphs:['DLKT branding, original interface and original service material belong to the operator or its licensors. Third-party articles, excerpts, data, names and marks remain subject to their owners’ rights and applicable licences. A link, excerpt or attribution does not transfer those rights or imply endorsement.','Follow the original publisher’s terms for reuse. Linking to a public DLKT card does not publish your saved personal briefing. Report an attribution or rights concern using the <a href="/sources#corrections">corrections and rights route</a>.']},
  {id:'availability',title:'Availability and changes',paragraphs:['Sources can fail, change format or withdraw access. Coverage and features may change, and the reader may be interrupted for maintenance or security. Local browser data can be lost if you clear site data, change browser or lose the device; browser saving is not a guaranteed remote backup.','We may restrict abusive access or suspend a feature where necessary to protect the service, users or legal obligations. Material changes to these terms will be reflected in this page’s date and, where applicable, additional notice. New data uses or charges do not become authorised merely because this page changes.']},
  {id:'rights',title:'Responsibility and your rights',paragraphs:['DLKT does not undertake a contractual guarantee of uninterrupted availability or the accuracy of independent publishers. Nothing in these terms excludes responsibility where it cannot lawfully be excluded, removes mandatory consumer protections or limits your statutory privacy rights.','These terms are governed by Estonian law subject to mandatory protections that apply to you, including relevant consumer protections in your country of residence. Court jurisdiction follows applicable law; these terms do not require every consumer to bring a dispute exclusively in Estonia. Contact us if there is a service concern. Your right to approach a competent authority or court remains available.']}
 ]},
 {slug:'privacy',updated:'27 November 2026',title:'Privacy, explained.',lead:'What this version processes, why it does so and the control you keep.',sections:[
  {id:'organizations',title:'Organization previews and pilot enquiries',paragraphs:['Organization reading filters are processed by the reader on your device against the connected source response. Saving an organization setup is optional and browser-local, with its own clear control. An optional organization name is kept in the current form only and is included in a pilot draft only when you choose Prepare pilot request.','The draft is not submitted to DLKT by the form. Opening the email draft transfers it to your email app or provider; you choose whether to send it. A sent enquiry is processed like other correspondence described below. There is no activated checkout, organization publication service or paid membership.']},
  {id:'controller',title:'Who is responsible',paragraphs:[`${COMPANY.name}, Estonian registry ${COMPANY.registry}, is the controller for processing it determines for DLKT. Registered office: ${COMPANY.address}. For a privacy request, email ${mail('Privacy request')}.`]},
  {id:'requests',title:'When you open or use the reader',paragraphs:['Hosting and network systems process request information such as IP address, requested URL, time, browser or device information and security signals to deliver pages and APIs, troubleshoot failures and protect against abuse. A visit is not represented as anonymous merely because you do not have an account.','City search sends the text you enter to DLKT. On entry, an approximate current city supplied by the hosting network selects the initial public city edition. The city can be corrected; this estimate does not establish your address or neighbourhood. An explicit location action uses your browser’s permission and sends a rounded position to DLKT to suggest nearby city centres. Weather requests use the selected city’s centre, not a precise personal address.','Normal interest filtering and Save or Remember actions keep reading choices in the browser. An explicit account import, when available, stores a separate private reader copy as described below. Preparing a downloadable edition explicitly sends selected topics, a text filter and card count to DLKT for that response. Avoid putting confidential or sensitive personal details into search filters.']},
  {id:'account',title:'Account sign-in and private reader copies',paragraphs:['When account sign-in is available, Supabase Auth processes the email address you submit, your account identifier, verification and sign-in timestamps, and session information needed to authenticate you. Requesting a code also sends your browser timezone (with UTC as a fallback) and the initial language setting, English. Creating an account creates a linked base profile using these values and account defaults. That base profile is separate from the optional Wallet preferences you choose to save. Requesting a sign-in code authorizes neither inbox access nor a subscription to briefing emails.','While signed in, Import from this browser explicitly sends a copy of your saved focus, source cards and comparison checkpoint to your private account. Restore in this browser explicitly replaces the corresponding local reader data with that account copy. These actions are not automatic background sync or a merge. Delete account reader copy removes that stored copy without deleting your sign-in account, Wallet preferences or existing browser copy.']},
  {id:'wallet',title:'Info Wallet and personal connections',paragraphs:['The Wallet screen shows whether account sign-in and private profile saving are available. When account sign-in is available, a signed-in user can choose Save profile to store optional Wallet preferences privately in their account. My profile and Info Wallet use the same optional private preference record. The profile page exposes display name, language, timezone and interests; Wallet additionally exposes preferred briefing time and personal-first or balanced preference. Saving from either screen preserves the fields it does not edit. Unsaved Wallet form edits are cleared when you leave the active view.','The preferred time is a preference, not a scheduled email or notification. Wallet preferences are kept separate from the base account profile, the account reader copy, public source cards and browser-local reader memory. Delete Wallet preferences removes those preferences; it does not delete the sign-in account, the account reader copy or browser reader memory.','Connection availability is shown in Wallet. Signing in or saving a profile does not grant access to an external account. Connecting an available provider requires a separate OAuth authorization in that provider’s account flow. Wallet explains supported account types, permissions, approval limits and available controls before you connect. Wallet profile details and connected activity are not included in public card links, downloadable public editions or shared source caches.']},
  {id:'connections',title:'Optional email and social account access',paragraphs:['When a connection is available and you authorize it, DLKT stores its provider, account label, connection status, connection time and last-check time in your private account. Provider access tokens, refresh tokens where supplied, and managed Facebook Page tokens are encrypted server-side before storage in Supabase. These provider credentials are not returned to page JavaScript or saved in browser storage.','Check updates performs a bounded read from the authorized provider. For an available and already-authorized connection, the signed-in homepage can also recheck about every sixty seconds while visible and focused, slowing down after failures. Gmail and Outlook supply email metadata such as sender, subject, time and a source link; this feature does not request message bodies or attachments. Instagram Business or Creator accounts and managed Facebook Pages can supply a limited sample of comments on their posts. The current feature does not retrieve personal direct messages, identify everyone who viewed or shared content, send emails, publish posts or modify comments. Instagram’s comment permission also permits moderation at the provider; DLKT uses it only to read comments.','Returned activity is processed by the DLKT server for the requested response and displayed transiently in the active Wallet or homepage account view. The homepage shows at most five recent metadata updates, with read status only when supplied by the provider. This connection feature does not save the returned email metadata or comment content to the account database or browser storage. The view is cleared when it loses focus, is hidden or left, when you sign out, or when its session can no longer be confirmed. A last-check timestamp is stored separately; it does not establish a complete activity history. This feature does not collect personal activity while the page is closed or provide scheduled personal delivery.','Disconnect removes the saved connection record and its encrypted credentials from DLKT. DLKT also requests provider revocation where supported; where this cannot be confirmed, Wallet instructs you to remove DLKT access in the provider’s account settings. Disconnect does not delete the original emails or comments, other saved DLKT data, or provider logs and backups. Signing out alone does not disconnect an external account.']},
  {id:'browser',title:'What stays on your device',paragraphs:['Saved focus, followed categories, cards, comparison checks, your personal briefing, explicit Useful/Not today feedback, a remembered city and daily-signal preferences are stored locally when you use the corresponding Save, Follow or Remember action. Local state can reveal your interests to another person using the same browser. An explicitly saved source check covers your chosen interests. Changes can be narrowed to saved card identities within those interests; this does not activate background monitoring or compare full article text.','DLKT’s public source cache is shared information, not an upload of your saved personal briefing. An account import is a separate explicit action. Local preferences are not sent as parameters to the public glance cache. The <a href="/cookies">browser storage page</a> describes the separate controls and retention.']},
  {id:'purposes',title:'Purposes and legal bases',paragraphs:['The first local view may use an approximate city supplied by the hosting network. It is labelled approximate, can be changed, and is not saved as a preference automatically. The current connection estimate takes priority over an older saved city on a new visit. A city you choose during the visit takes priority over a later estimate; saved comparisons and personal reading stay separate. GPS is requested only after choosing the location control.','Delivery, troubleshooting and proportionate security processing serve our legitimate interests in operating a usable and secure information service under GDPR Article 6(1)(f). Optional location processing relies on your requested action and permission under Article 6(1)(a); you can withdraw the browser permission without losing ordinary city search. Withdrawal does not affect the lawfulness of processing before withdrawal.','Providing account sign-in and the private profile or reader copy you request relies on Article 6(1)(b), as necessary to provide those requested account services. Handling a legal obligation, including an applicable rights request, relies on Article 6(1)(c). Ordinary correspondence is processed under Article 6(1)(f), our legitimate interest in answering enquiries and resolving service concerns; correspondence needed for steps you request towards a contract may rely on Article 6(1)(b). Reading does not mean consenting to advertising or an unrelated data use.']},
  {id:'recipients',title:'Providers, links and international processing',paragraphs:[`Vercel supplies hosting, content delivery and operational/security infrastructure. Its service arrangements include ${external('data-processing terms and international transfer safeguards','https://vercel.com/legal/dpa')}, including applicable contractual clauses. A European function region does not imply that every network, security or support operation stays in the EEA. Contact us for information about safeguards relevant to your request.`,'When account sign-in is available, Supabase provides account authentication and stores the base account profile, optional Wallet preferences and any reader copy you explicitly import. For a connection you authorize, Supabase also stores the connection record and encrypted provider credentials described above. Google, Microsoft or Meta processes the authorization and API requests for its corresponding connected service. Resend delivers transactional authentication emails, processing the recipient address, message content and delivery information. This does not connect your inbox to DLKT or activate marketing or scheduled briefing emails. Provider processing is distinct from the browser-local reading tools; a selected project region does not establish that every provider operation takes place in that region.','Source requests made by DLKT use fixed publisher endpoints and selected city coordinates where relevant. Mapped places, where available, use a bounded Private.coffee Overpass request with public city-centre coordinates, not your precise position. Data is credited to OpenStreetMap contributors under ODbL. Bucharest may show a small curated Wikidata CC0 reference set, reviewed 17 November 2026, instead of a live map request result. Direct discovery searches send their query to the map or publisher only when opened. Opening an original-source link makes a separate connection to that publisher, whose own privacy terms apply. Choosing a sharing or email app also uses that app’s handling rules.','If you email us, your address, message and any attachments are processed by the company’s email service and the people handling the enquiry. We do not use the current reader to sell your saved reading profile or run advertising trackers.']},
  {id:'audience-measurement',title:'Audience measurement',paragraphs:['Optional first-party audience measurement may be available on the news reader. It is off unless you expressly choose Allow audience measurement in the <a href="/cookies#cookies">Cookies settings</a>. DLKT Group OÜ uses it to understand readership, service adoption and traffic patterns, under consent (GDPR Article 6(1)(a)). Declining does not restrict reading or account services. We do not use this feature for advertising or personal profiling.','When enabled, the reader records page entries, recent activity, a random browser pseudonym, approximate country and city at session entry when available, and a coarse traffic-source group. It does not collect GPS coordinates, raw IP addresses into the audience store, article titles, full URLs, search terms, account identities or a device fingerprint. Vercel supplies network-derived approximate geography; Supabase hosts the separately configured audience data. The hosting and provider safeguards described below still apply.','The measurement cookie expires after 90 days. The audience store is subject to a 90-day rolling retention policy and scheduled deletion. Browser counts are estimates of consenting browsers, not people. Geographic groups with fewer than three measured browsers are suppressed. Only authorized administrators can see aggregate reports.','You may stop measurement and request deletion of linked audience activity at any time using Do not allow / withdraw in Cookies settings. The reader stops sending measurement events immediately; the control reports whether server deletion was confirmed. A pseudonymous revocation marker is retained for up to 90 days to prevent stale requests from recreating deleted activity. Clearing the browser token alone may prevent us from locating earlier linked activity. Contact us for privacy requests. Operational and security logs and provider backups are separate from this measurement store.']},
  {id:'retention',title:'How long information remains',paragraphs:['Browser choices remain until replaced, removed with the corresponding control or cleared by the browser/device. Their source cards can expire for display without deleting every stored local record. Operational request logs expire under the hosting service’s configured rolling retention, unless a relevant record needs to be preserved for an investigation or legal obligation. You can ask the company contact for the period relevant to a specific request.','Saved Wallet preferences and account reader copies remain in account storage until replaced or removed through their respective controls, or handled through an applicable account or privacy request. Signing out or clearing browser data does not delete server-side account records. Removing either saved copy does not delete the Supabase Auth account or its linked base profile. For account deletion or questions about provider logs and backups, use the privacy contact below; the in-product delete controls do not promise immediate erasure of those separate records.','Correspondence is kept while needed to answer and follow up the request, and where necessary for a legal obligation or a documented dispute. Incident-related information is retained only as needed to investigate, protect the service and meet applicable obligations. Public source caches use their technical freshness limits; they are separate from personal correspondence.']},
  {id:'rights',title:'Your choices and rights',paragraphs:[`Where applicable, you may request access, correction, deletion, restriction or portability, object to legitimate-interest processing and withdraw consent for optional processing. Email ${mail('Privacy request')} with enough context to locate the relevant processing, without sending passwords or unnecessary identity documents. We may need proportionate identity verification. We normally respond within one month of receiving a rights request. Where the law permits an extension, we explain it and the reasons within the initial month.`,'You may complain to a competent data-protection authority, including one in your country of residence. The Estonian authority is <a href="https://www.aki.ee/en" target="_blank" rel="noopener noreferrer">Andmekaitse Inspektsioon</a>. You do not have to give up that route to contact us.']},
  {id:'decisions',title:'Personalisation and future features',paragraphs:['The optional personal briefing uses chosen interests, city, source dates, availability and explicit browser feedback. The public news stream uses selected language, the selected country edition and shuffled category rounds. National priority describes the publisher edition, not a conclusion about where an event happened. DLKT does not make an automated decision about you with legal or similarly significant effects, such as deciding eligibility for credit, work or insurance.','Additional connection capabilities, advertising, paid products or materially different data uses require an updated notice and any additional choice or legal basis that applies. Their availability must not be inferred from account sign-in or private profile saving.']}
 ]},
 {slug:'cookies',updated:'27 November 2026',title:'Cookies & browser storage.',lead:'A practical inventory of the current reader and how to remove local choices.',sections:[
  {id:'cookies',title:'The current cookie position',paragraphs:['The public reader does not use advertising cookies or third-party advertising or analytics scripts. Hosting/security mechanisms process request metadata and may use technical protection cookies when necessary. The privacy notice explains those purposes. When account sign-in is available and you sign in, the first-party session cookies described below support your authenticated requests. Ordinary public reading does not require signing in.','Optional audience measurement is off by default. Allow audience measurement stores a first-party Secure, HttpOnly, SameSite=Lax cookie named <code>__Host-dlkt_audience</code>, containing a signed random browser token with a maximum lifetime of 90 days, and a local preference named <code>dlkt-audience-choice-v1</code>. The preference stores your choice, not an identifier; it remains until changed or cleared. Measurement helps DLKT understand readership using page entries, recent activity, approximate session-entry geography and broad traffic-source groups. It is separate from your account and saved reading choices.','Do not allow / withdraw stops measurement in this browser and requests deletion of linked activity if a valid token is available. If deletion is not confirmed, the control lets you retry. You can read without making any choice. See the <a href="/privacy#audience-measurement">audience privacy notice</a> for retention, revocation markers, providers and rights.','<button id="audience-choice-allow" class="secondary" type="button" hidden>Allow audience measurement</button> <button id="audience-choice-deny" class="secondary" type="button" hidden>Do not allow / withdraw</button>','<span id="audience-choice-status" role="status" aria-live="polite">Optional audience measurement is off unless you have expressly allowed it. Checking availability requires JavaScript.</span>']},
  {id:'session-cookies',title:'Account session cookies',paragraphs:['<code>__Host-dlkt_info_at</code> carries the access credential for authenticated account requests. Its browser lifetime is up to 1 hour: it is set to the provider-reported expiry minus 30 seconds, bounded between 60 and 3600 seconds.','<code>__Host-dlkt_info_rt</code> carries the refresh credential used to renew an authenticated session. Its browser lifetime is 30 days from when it is set or renewed. A cookie lifetime is not a guarantee that the server will accept the session for that entire period.','Both cookies use Secure, HttpOnly and SameSite=Lax, with Path=/ and no Domain attribute. They are scoped to the host that sets them, sent over HTTPS and unavailable to page JavaScript. DLKT does not put these credentials in localStorage, sessionStorage or IndexedDB. Signing out clears both cookies on that host and requests termination of that session; it does not sign out every other device or delete saved account data.']},
  {id:'connection-cookies',title:'Connection authorization cookies',paragraphs:['Choosing Connect for an available provider sets a temporary first-party cookie for that authorization: <code>__Host-dlkt_connection_gmail</code>, <code>__Host-dlkt_connection_outlook</code>, <code>__Host-dlkt_connection_instagram</code> or <code>__Host-dlkt_connection_facebook_pages</code>. It holds an unpredictable authorization-state value used to bind the callback to the connection request and signed-in session; it does not contain the provider access token.','Each authorization cookie has Max-Age=600, a lifetime of 10 minutes, and uses Secure, HttpOnly and SameSite=Lax with Path=/ and no Domain attribute. It is unavailable to page JavaScript and is cleared when the corresponding recognized callback is handled. The authorization request also expires after 10 minutes. Deleting this cookie can prevent an in-progress connection from completing; it does not delete an existing server-side connection.']},
  {id:'inventory',title:'What the browser can remember',paragraphs:['IndexedDB reader memory stores explicitly remembered interests, followed editorial categories, saved source cards, comparison snapshots, a personal briefing and its feedback. A separate local-city store remembers a city and source comparison when you choose Remember city.','Daily-signal settings use local storage under dlkt-glance-preferences-1. They contain visibility choices and a reference currency. The homepage presents available weather and currency references as static controls. A moving headline ribbon is not activated in this release. Any dlkt-ticker-motion-v1 value left by an earlier version is ignored. These settings are separate from a browser’s location permission.']},
  {id:'following',title:'Followed topics',paragraphs:['Follow on a card stores its displayed editorial category and, when available, a current source-listing comparison in the reader IndexedDB meta store under dlkt-category-follow-v1. These category choices and baselines stay in this browser; they are not included in account import, account restore or reading exports.','The homepage compares the existing public source snapshot against these saved checks while open. A reload does not advance the baseline. Save current check explicitly replaces the baseline for that category; Stop following removes that category and its baseline. Clear reader memory in Personalise removes all followed categories. This does not activate notifications, article translation or monitoring while the page is closed.']},
  {id:'reading-language',title:'Reading language',paragraphs:['The language control remembers only your explicitly selected language under <code>dlkt-reader-language-v1</code> in local storage. This choice is used for the interface and for selecting available original news in that language. An explicit language in a link applies to that visit without replacing the saved choice.','On a first visit without a saved choice, an approximate country from the existing connection hint can set the initial language. Selecting a home city then sets the default language for its country, unless you have explicitly chosen a language. A late connection estimate cannot replace that selected country. Exploring another place or restoring a saved city does not silently replace your reading language. Browser language preferences help choose between supported local languages in multilingual countries. The estimate is not proof of your language, residence or nationality; it does not request GPS or save your location. You can always choose English or another listed language.','The language code contains no city, interests, saved articles or account data and is not sent to publishers. It remains until changed or cleared in browser site data. Clearing reader or city memory is separate. When local storage is unavailable, the control still works for the current page and its URL. Original publisher text is not automatically translated; missing language coverage stays explicit.']},
  {id:'appearance',title:'Reader appearance',paragraphs:['The light/dark control remembers only your chosen light or dark appearance under <code>dlkt-reader-theme-v1</code> in local storage. It writes only when you use that control; a first visit uses the light appearance without saving a choice. The value contains no city, interests, saved cards or account data and is not sent to DLKT.','Use the same control to change the appearance, or clear this origin’s site data in browser settings to remove the choice. It remains until changed or cleared; clearing reader or city memory is separate. If browser storage is unavailable, the control still changes the appearance for the current page.']},
  {id:'controls',title:'Remove or change your choices',paragraphs:['Open Personalise on the reader to review or clear reader memory, including remembered focus, followed categories, cards, comparison and personal briefing. Daily-signal preferences reset with that reader-clear action. Use Forget saved city in the local view to remove the separately remembered city and comparison.','You can also clear this site’s storage in your browser settings. Browser storage belongs to the site origin where it was created. The current platform is www.dlkt.ee; clearing its storage does not clear a separate origin you may have used in the past. Clearing local storage or session cookies does not remove your sign-in account, saved Wallet preferences, account reader copy or server-side connections. Use Disconnect in Wallet for an external account and remove provider authorization separately where instructed. Use their separate account controls or the privacy contact for those records. A downloaded reading copy or a file you shared is outside the browser store and must be managed separately.','Use Customize to change the daily signals without clearing saved cards. Revoke location permission in browser settings if you previously enabled it. Ordinary city search remains available without it.']},
  {id:'organization-setup',title:'Organization setup',paragraphs:['The optional organization setup uses local storage under dlkt-organization-setup-v1 only after Remember this setup. It contains the selected pilot plan, source topics, reading length and optional text filter. It contains no organization name or email address. Use Clear saved organization setup on <a href="/organizations">For organizations</a>, or clear this origin’s site data, to remove it. Reader and city clearing are separate.','A preview link includes the selected source topics and filter in its URL fragment. Use public filter terms. No account, membership or organization verification is created by that link.']},
  {id:'duration',title:'Duration and changes',paragraphs:['Browser-local reading choices have no promised automatic deletion date; they remain until replaced, cleared or removed by the browser/device. Expired source content may stop appearing as current while a saved comparison remains on the device.','If optional tracking or a new storage purpose is introduced, its purpose, duration and applicable choice must be explained before activation. <a href="/privacy">Read the privacy notice</a> for hosting and enquiry data.']}
 ]},
 {slug:'disclaimer',updated:'22 November 2026',title:'Information, with context.',lead:'What a source-linked update establishes, and what it does not.',sections:[
  {id:'general-coverage',title:'General-interest coverage',paragraphs:['The reader combines reviewed official feeds, licensed community reporting and source-checked news headlines across broad and specialist subjects. Global Voices and Electronic Frontier Foundation retain their named author, translation and licence credits where applicable. These are attributed reports, statements and perspectives; selection does not establish independent corroboration.','Coverage depends on the connected publishers and their availability. Sport, culture, business and other topic groups do not imply complete worldwide or neighbourhood coverage. Consumer prices, ticket availability and incident status require a relevant current source. Several feeds from one publisher do not become several independent confirmations.']},
  {id:'scope',title:'Coverage and publisher claims',paragraphs:['DLKT aggregates selected connected sources. It does not cover every publisher, city, event or development. A source check validates the supported source record and presentation rules; it is not independent corroboration of every statement in that record.','Publication dates, update dates, forecast periods and the time DLKT checked a source are different. A recent check does not make an older publication new. Scope and Next step describe the connected publisher and how to inspect its original record; they do not determine whether an item personally affects you. The selected country prioritises available reporting from its reviewed publisher editions within each category. A national publisher can report on events abroad; its country is not the location of the event. A local label requires separately supported city relevance. This is not a ranking of all world news.']},
  {id:'decisions',title:'Health, financial and legal decisions',paragraphs:['General health, economic, legal or public-affairs information is not individual medical, investment, tax or legal advice. Regulatory announcements can have a particular country’s scope. Check the original document and an appropriately qualified professional where a decision requires one.','ECB figures are dated reference exchange rates, not executable prices or a live trading feed. Any percentage change shown by DLKT is calculated between the identified published references. No investment return or financial outcome is promised.']},
  {id:'local',title:'Weather, transport and events',paragraphs:['Weather is a city-centre forecast for the stated period, not measured conditions at your address or an official emergency warning. Its illustration follows the current forecast-hour condition and day or night symbol supplied by the weather source. Unknown or expired conditions use a neutral illustration. Figures combined or converted by DLKT are labelled. Forecasts and operator notices can change.','A listed event is not a booking, a guarantee of admission, a verified ticket price or confirmation that a seat is available. Check the organiser. Missing or unavailable transport, weather or local coverage is not an all-clear. Use the relevant official emergency and travel channels when necessary.']},
  {id:'sources',title:'Original sources and corrections',paragraphs:['External sites have their own content, terms and privacy practices. Publisher names and marks identify sources and do not imply endorsement of DLKT. Third-party rights remain with their holders.','Report a presentation, extraction, attribution or rights issue through <a href="/sources#corrections">Sources & method</a>. Nothing in this notice waives rights or excludes responsibility that cannot lawfully be excluded.']}
 ]},
 {slug:'sources',updated:'22 November 2026',title:'Sources & method.',lead:'Original publishers, visible dates and clear limits on what each update means.',sections:[{id:'bucharest',title:'Bucharest: heating, hot water and events',paragraphs:["Termoenergetica Bucuresti (CMTEB): short factual summaries by sector from the public heating and hot-water status table at <a href=\"https://www.cmteb.ro/functionare_sistem_termoficare.php\" target=\"_blank\" rel=\"noopener noreferrer\">the official operator page</a>. Restoration times are estimates, not confirmed outcomes. Street examples do not identify your address; household details are not reproduced. Each check expires after five minutes.", "ARCUB: the <a href=\"https://arcub.ro/agenda\" target=\"_blank\" rel=\"noopener noreferrer\">official agenda</a> and up to six linked event pages. Only explicitly published, matching years and times become dated schedules. Date-only ranges do not establish current opening hours. Confirm tickets and changes with the organiser. These sources do not cover every service or event in Bucharest.", "The news stream includes eligible global and local articles in the chosen reading language, arranged in shuffled category rounds. Each available category appears once per round; available national-edition reporting comes before international reporting within each category. City weather, service notices and other practical records remain in a separate city section below the news. A headline place mention is not proof that an event affects you, and the publisher's home country is not treated as the event location. Foreign bulletins retain their actual jurisdiction."]},{id:'local-reporting',title:'Connected local journalism',paragraphs:['Bucharest reporting currently uses B365 and Buletin de Bucuresti RSS feeds. Each displayed item must identify the city through an explicit place reference in its headline or bounded excerpt; publisher country alone is insufficient. Source checks expire after five minutes. Publication dates are preserved and do not establish when an incident occurred. Sources unavailable at the current check remain labelled unavailable.', "B365: no more than 250 characters of headline and excerpt combined, linked to the original report. Buletin de Bucuresti: no more than 500 characters combined, with the named author, publisher, original link and CC BY 4.0 licence for the licensed text. Full article bodies are not copied. Original-article photo previews follow the method below; a text licence is not applied to a photograph. The local text-source terms were reviewed on 18 November 2026 and are due for review again by 18 December 2026.", "Eligible local reports in the chosen reading language join the continuous news stream through the same category rounds, without an eight-report limit or a per-publisher or per-topic display quota. Exact record IDs and article URLs are deduplicated; distinct original articles remain available even when their headlines match. Freshness, identity and source checks still apply, and connected-source coverage remains partial. Multiple CMTEB sector records may be grouped into one practical city overview without inferring your sector or building.", 'Two connected Bucharest publishers do not constitute a worldwide local-news network. Other cities retain the current connected coverage shown in the reader. Additional publishers require verified access, rights, geography and source behaviour before connection.']},{id:'local-discovery',title:'Local discovery and place references',paragraphs:['Connected local information remains limited to the sources and cities shown by the reader. Optional OpenStreetMap places are city-centre reference points, credited to OpenStreetMap contributors under ODbL, accessed through Private.coffee Overpass. They do not establish opening hours, current events, prices or availability. A small Bucharest fallback uses Wikidata CC0 structured-data references reviewed on 17 November 2026.','Direct links to an organiser, authority, publisher or map search are labelled as exploration. Those destinations are not represented as connected DLKT feeds, and their creative article text, titles and photographs are not republished through this feature.']},
  {id:'method',title:'How a card reaches the reader',paragraphs:['The service reads reviewed, fixed publisher feeds and supported source documents. It checks source identity, format, required fields and freshness boundaries before displaying a record. Unsupported or unavailable material is not replaced with an invented story.','Source titles and bounded publisher excerpts remain attributed. Extracted passages are selected passages, not a complete report or a generated factual verdict. Comparisons describe supported changes between checks; absence from a feed does not establish that an event ended or a notice was withdrawn.']},
  {id:'publishers',title:'Connected topic publishers',paragraphs:publisherParagraphs},
  {id:'local-sources',title:'City and daily reference sources',paragraphs:[`${external('MET Norway','https://www.met.no/en')} supplies city-centre forecasts under CC BY 4.0. ${external('GeoNames','https://www.geonames.org/export/')} supplies the city catalog under CC BY 4.0. London Tube information uses ${external('TfL Open Data','https://tfl.gov.uk/corporate/terms-and-conditions/transport-data-service')} with the attribution shown in the reader.`,'Palma has selected municipal culture listings, council announcements and TIB transport notices. Other cities have different connected coverage, shown in the local view. This is not a nationwide or worldwide local-news network.',`${external('ECB reference exchange rates','https://www.ecb.europa.eu/stats/policy_and_exchange_rates/euro_reference_exchange_rates/html/index.en.html')} are available free from the ECB. DLKT identifies its calculations and keeps the reference date visible. Each source’s own terms and attribution remain relevant.`]},
  {id:'selection',title:'Country editions and daily reference signals',paragraphs:["The selected city determines the country edition and the separately available local information. Within each news category, reporting from reviewed publisher editions in that country comes before eligible international reporting. This describes publisher provenance, not the event location. Source dates and freshness checks still apply. Optional personal briefings can use selected topics. Static weather and ECB reference controls keep practical signals separate from the article stream; the homepage does not label ordinary headlines as breaking news.",'The service does not represent all available publishers as independent corroboration of a claim. Sponsorship, if introduced, must be identified separately from editorial/source material. This release does not activate advertising or paid ranking.']},
  {id:'photographs',title:'Photographs and image credits',paragraphs:["A news card can show an individually reviewed source photograph bound to that exact article, or an image identified in that article's original publisher metadata. DLKT does not substitute a category image, stock photograph, contextual picture or unrelated portrait. The publisher may itself use an archive photograph, collage or illustration; an original-article preview does not establish that the image depicts the reported event.","Article-photo previews are served by DLKT in a uniform 16:9 frame with proportional cropping, without stretching. The Source photo link leads to the original article, where publisher captions, the full image and rights information can be checked. Separately reviewed photographs retain their recorded credits. DLKT does not invent an author or infer a photo licence from the article text, metadata or source link. If the original image is unavailable or fails to load, the article title and source actions remain visible. The separate branded share download remains a text and source preview."]},
  {id:'consumer-sources',title:'Consumer and cyber-security sources',paragraphs:['The UK OPSS feed lists product safety alerts, reports and recalls. Its Updated date is the feed update, not necessarily the original recall date. Check the exact model, batch, affected country and instructions in the original. It does not cover every country or food, vehicles and medicines.',"NCSC contributes UK cyber-security news under the Open Government Licence v3.0. Its stated audience and jurisdiction remain relevant; a news entry does not establish a personal breach or device vulnerability. Article-photo previews follow the original-image method above and do not acquire a licence from the text attribution.",'Shared cards can expose a source-dated DLKT preview image and a download link. Images include only public card metadata and the DLKT brand. A generic brand preview is used when the original title or required credits cannot be rendered faithfully. Open the card for complete source credits and the latest available check. Social services may cache their own previews.']},
  {id:'daily-top',title:'News categories and continuous reading',paragraphs:[`The public news stream uses the ${NEWS_CATEGORIES.length} top-level IPTC Media Topics: ${NEWS_CATEGORIES.map(category=>category.iptcLabel).join('; ')}. The concept identifiers and standard names come from ${external('IPTC Media Topics','https://www.iptc.org/std/NewsCodes/treeview/mediatopic/mediatopic-en-US.html')}. DLKT infers an article's category from canonical publisher sections and keywords, headline wording and supported source hints. This is an editorial inference, not an IPTC certification of each article. Short reader labels and Romanian translations are DLKT's.`,
  "The news stream cycles through all currently available categories in a shuffled order. Each active category contributes one article before the next round starts. When another category is available, the first article of a new round differs in category from the preceding article. Categories with no remaining articles leave later rounds; when only one remains, all its remaining articles stay available. The category order stays stable for the displayed edition while more cards load. A category filter shows a projection of that same order. The selected country gives available national-edition articles priority within each category. Other editorial signals order articles inside each national or international group; saved interests do not silently remove articles from the public stream. The reading language still applies: DLKT selects available reporting in its original language, and English remains an explicit option. Choosing English does not translate other-language articles. Headline developments, source observations, freshness and diversity inform editorial priority; it is not a measured worldwide popularity or importance ranking.",
  "The stream retains every eligible, unique article from the available global and local catalogue. Category rounds affect order, not membership. Up to twenty articles are displayed initially, and reaching the end loads the next group of up to twenty automatically where supported. A labelled button remains available for manual loading. Category filters show matching and overall counts without imposing a total display ceiling. Articles without a supported category remain available as Other topics. Source, date and integrity checks remain mandatory; the catalogue is bounded by connected-source coverage and collection capacity.",
  "The global publication selection uses original publication dates within a rolling twenty-four-hour window. A source check, index appearance, modification or legal document date cannot make an older story new. Local reports retain their separately reviewed publication and checking windows. Every article keeps its original date and publisher link, and other dated official records remain available through the relevant reader views.",
  "Discovery combines the GDELT Article List and reviewed publisher news indexes. A newly admitted article requires its URL, headline and original publication date to be checked against the original publisher page. Bounded candidate rotation progresses across refreshes. Earlier verified articles may remain while still eligible, with their original observation timestamps and content hashes; retention is not a new source check. An original selected for reverification is not restored from retained data if that verification fails. This is partial coverage of connected sources, not a search of every page on the web.",
  'An article found among the first ten matching links inside the main content of a reviewed publisher homepage receives a placement signal. AP, The Guardian, PC Gamer and BBC are checked with strict time and size limits. This records the publisher placement observed at the check; it does not measure worldwide popularity, independently corroborate the story or certify its importance. Source availability, subject diversity, headline signals and recency inform editorial priority within each category.',
  'News discovery is scheduled every two minutes, with scheduling jitter and bounded collection time. Official feeds retain their own reviewed check intervals, which can be longer. Actual successful checks are recorded separately from the schedule. Public page requests read the shared catalogue and do not start another publisher collection. While visible, the page checks for updates every thirty seconds; failures back off and hidden pages stop polling. New or changed publications are announced through Show updates, leaving the current reading order stable. Expired publications leave the daily top. A source outage can temporarily preserve a recent successful check with its original timestamp; it never becomes a new verification. This is periodic discovery of connected sources, not an instantaneous worldwide news service. The candidate cache is bounded and separate from permanent shared-card history. The refresh sends no personal email or notification.',
  "The news stream displays attributed headlines, original publication dates, source links and, when available, original-article photo previews as described above. It does not republish full article bodies, bypass paid access or turn an inaccessible article into a verified card. Original publishers and image owners retain their rights; a source link or displayed preview does not grant a reuse licence."]},
  {id:'country-coverage',title:'National and local coverage',paragraphs:['The selected city supplies a reviewed country code. A national count means eligible articles from reviewed publisher editions for that country in the selected reading language. It is not a count of independently verified events inside that country. The local count uses separately verified city sources, and the international count describes the remaining eligible reports. These three counts describe the full current edition, not just its first page.','A country with no eligible national articles displays that shortfall and keeps available international reporting accessible. English is an explicit reading option, not an automatic translation service. The Italian national supply starts with the official la Repubblica RSS index, with each admitted article checked against its original publication metadata. One connected national publisher does not constitute complete coverage of Italian journalism or verified local reporting for Torino. Connected country coverage must expand through individually reviewed source access, identity, rights and freshness.']},
  {id:'news-publishers',title:'Reviewed news publishers',paragraphs:[`The discovery allowlist includes ${NEWS_PUBLISHERS.length} publisher families. Being on this list does not mean every publisher was available in the latest check, every category was covered or a full-text licence was granted. Actual source state and card credits remain visible.`,NEWS_PUBLISHERS.map(publisher=>external(publisher.label,publisher.origins[0]??'https://www.gdeltproject.org/')).join(' · ')]},
  {id:'general-sources',title:'Community reporting and digital rights',paragraphs:['Global Voices world and arts-and-culture feeds provide English-language community reporting and perspectives under CC BY 3.0. Original and translation credits from each feed entry are retained. Electronic Frontier Foundation Deeplinks provides digital-rights advocacy under CC BY 4.0 for its original material. These reviewed feeds can supply bounded excerpts under their stated terms; the broader news discovery shows headline metadata and original links.',
  "Available author and licence credits remain visible in the reader, shared card and downloaded reading copy. Duplicate record IDs, article identities and canonical article URLs do not create extra stream positions. Distinct original reports remain available even when their headlines match. Conflicting identities are isolated. Publisher statements, advocacy, reporting and research retain their provenance; placement is not evidence of independent agreement."]},
  {id:'corrections',title:'Corrections, copyright and concerns',paragraphs:[`Email ${mail('Correction or content rights')} with the DLKT page/card link, original-source link, relevant date and a concise description of the issue. For a rights claim, explain the material and your relationship to it; do not include unnecessary sensitive documents.`,'We can review DLKT’s extraction, attribution and presentation. A correction to an original publication may also require contacting its publisher. A complaint is assessed on its evidence; submitting one does not automatically establish that a claim is false or that you own the material.']}
 ]},
 {slug:'accessibility',updated:'22 November 2026',title:'Reading at your pace.',lead:'Visible controls, readable contrast and a stable path through the news.',sections:[
  {id:'features',title:'What the reader supports',paragraphs:['The interface uses labelled controls, keyboard focus indicators, semantic headings and source dialogs. Date and location remain visible, with an explicit Use my location action and manual city selection. Weather and currency references are static controls. No moving headline ribbon is activated on the homepage. Additional news loads without changing the displayed prefix, and a labelled loading button provides a manual alternative.','Weather illustrations use gentle loops only for a current, supported forecast condition. They become static with reduced motion and pause when hidden, offscreen or covered by a dialog. The layout adapts to narrow screens. Saved choices can be used without a personal account, and failure of browser storage does not stop ordinary reading.']},
  {id:'limits',title:'Known boundaries',paragraphs:['We do not claim certified conformance to every accessibility standard. External publisher pages and downloadable source documents are controlled by their publishers and may have different accessibility. Source pages may require their own account, subscription or accessible alternative. Use the contact below if a DLKT control, contrast or layout blocks reading.']},
  {id:'feedback',title:'Report a barrier',paragraphs:[`Email ${mail('Accessibility feedback')} with the page, task you were trying, device/browser and any assistive technology relevant to the problem. Share only the information needed to describe it. The same published company contact is available on the <a href="/contact">contact page</a>.`]}
 ]},
 {slug:'company',title:'Company details.',lead:'The operator behind DLKT.',sections:[
  {id:'identity',title:COMPANY.name,paragraphs:[`Estonian private limited company. Registry code: ${COMPANY.registry}. Register: Estonian e-Business Register. ${external('View the official company entry',COMPANY.register)}.`,`Registered office: ${COMPANY.address}. This is a registered office address, not a promise of a staffed public customer-service location.`]},
  {id:'contact',title:'Company contact',paragraphs:[`Email: ${mail('Company enquiry')}. This is the official company contact for DLKT. Privacy, source corrections and accessibility requests can use this contact with the relevant subject.`,'The DLKT platform and its current terms are published at <a href="https://www.dlkt.ee/">www.dlkt.ee</a>. These company details identify its operator; they do not introduce a separate product or destination.']}
 ]},
 {slug:'contact',title:'Let’s put it right.',lead:'A direct company contact for questions, privacy and source concerns.',sections:[
  {id:'enquiries',title:'Contact DLKT',paragraphs:[`Write to ${mail('Service enquiry')} for a service enquiry. For privacy, use the subject “DLKT · Privacy request”; for a source concern, include “Correction or content rights”; for an accessibility barrier, include “Accessibility feedback”.`,'Include the page or card link and the information needed to understand the request. Please do not send passwords, access tokens or unrelated sensitive documents. Opening an email link creates no submitted message in DLKT; you decide whether to send it in your email app.']},
  {id:'operator',title:'Operator and formal correspondence',paragraphs:[`${COMPANY.name}, Estonian registry ${COMPANY.registry}. Registered office: ${COMPANY.address}. <a href="/company">Company details and official register link</a>.`,'This contact is not an emergency service, a medical consultation, investment advice or a route to book an event. Use the original provider or the relevant official service for those actions.']}
 ]}
];
export function footerHtml():string {
 return `<footer class="site-footer"><div class="footer-main"><div class="footer-identity">${footerBrandLink()}</div><nav class="footer-nav" aria-label="Information and legal"><a class="footer-link" href="/about">About DLKT</a><a class="footer-link" href="/sources">Sources &amp; method</a><a class="footer-link" href="/organizations">For organizations</a><a class="footer-link" href="/contact">Contact</a><a class="footer-link" href="/company">Company</a><a class="footer-link" href="/accessibility">Accessibility</a><a class="footer-link" href="/terms">Terms</a><a class="footer-link" href="/privacy">Privacy</a><a class="footer-link" href="/cookies">Cookies</a><a class="footer-link" href="/disclaimer">Disclaimer</a></nav></div><div class="footer-bottom"><p>© 2026 DLKT Group OÜ</p><a class="footer-link" href="#top">Back to top <span aria-hidden="true">&#8593;</span></a></div></footer>`;
}
export function renderLegalDocument(doc:LegalDocument):string {
 const toc=doc.sections.map(s=>`<a href="#${e(s.id)}">${e(s.title)}</a>`).join('');
 const sections=doc.sections.map(s=>`<section id="${e(s.id)}"><h2>${e(s.title)}</h2>${s.paragraphs.map(p=>`<p>${p}</p>`).join('')}</section>`).join('');
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#f66061"><meta name="description" content="${e(doc.lead)}"><title>${e(doc.title)} — ${BRAND_NAME}</title><link rel="canonical" href="https://www.dlkt.ee/${doc.slug}"><link rel="shortcut icon" href="/favicon.ico?v=kate-fb7b2e60" type="image/x-icon"><link rel="icon" href="/favicon-kate-fb7b2e60.png" type="image/png" sizes="180x180"><link rel="apple-touch-icon" href="/kate-head.png"><link rel="manifest" href="/manifest.webmanifest"><link rel="stylesheet" href="/iceo.css"><link rel="stylesheet" href="/header.css"></head><body id="top" class="legal-page"><a class="skip" href="#legal-content">Skip to content</a><header class="masthead site-header"><div class="masthead-inner">${headerBrandLink()}<a href="/" class="text-button">Back to news <span aria-hidden="true">&#8599;</span></a></div></header><main id="legal-content" class="legal-shell"><header class="legal-heading"><p class="intro-caption">${BRAND_NAME} <span aria-hidden="true">/</span> TRUST &amp; INFORMATION</p><h1>${e(doc.title).replace(/\.$/u,'<span class="title-dot">.</span>')}</h1><p class="legal-lead">${e(doc.lead)}</p><p class="legal-updated">Updated ${doc.updated??LEGAL_UPDATED}</p></header><nav class="legal-toc" aria-label="On this page">${toc}</nav><article class="legal-copy">${sections}</article><a href="/" class="primary legal-return">Back to news <span aria-hidden="true">&#8594;</span></a></main>${footerHtml()}</body></html>`;
}
